import type { SpriteDef } from '../sprite.ts';

/**
 * Act 4, «Дирекция»: the executive floor at the top of the company. Quiet, expensive and wrong:
 * dark wood panelling or green damask, a coffered ceiling with brass lamps, a thick bordeaux carpet,
 * portraits without faces, binders that are all the same. One kit for the reception / waiting hall,
 * the meeting room, the library-office and the office of «Главный цензор».
 *
 * Scale v3.1 (hero 86 px): floor line (feet) at y = 172, ceiling strip y 0..22.
 * - Structure tiles repeat horizontally, anchor top-left: di2_ceiling at y = 0 (rows 21-23 start the
 *   crown moulding), di2_wall / di2_wall_b at y = 22, di2_floor at y = 172. Chair rail at y = 122.
 * - Floor props: anchor bottom-centre on the floor line. Chair seats 30 px up, table top 40, the
 *   censor's desk 44, the reception counter 54.
 * - Wall props (window, portrait, emblem, seal): anchor centre, intended y in each comment.
 * - Ceiling pieces: di2_lamp anchor top-centre at y = 4; di2_projector anchor top at y = 22.
 * Colours are local (lit) values. Emissive bits: lamp glass, the banker's lamps, the picture lights,
 * the projector screen and lens, the window slats in the flash frame. No lettering anywhere.
 */

